-- 005_eventos_abiertos.sql
-- ECP_DIFERIDAS · Cierra el punto 3: hace USABLE la duracion marcando los eventos ABIERTOS.
--
-- HALLAZGO (al validar DUR_HORAS de la 004)
--   END_DATE usa valores CENTINELA muy en el futuro para decir "el evento sigue abierto":
--   2124-12-06, 2123-01, 2125-05... Son 18.472 filas (1,6%).
--   Efecto: la duracion MEDIA salia 54.368 h (~6,2 años) cuando la real es 446,9 h (~18,6 dias)
--   -> los centinelas la inflaban 122x. Entregar DUR_HORAS asi seria entregar un dato que engaña.
--
-- SOLUCION
--   * EVENTO_ABIERTO (0/1): 1 cuando la fecha de fin supera el ultimo dia con datos (DIM_CORTE).
--   * DUR_HORAS pasa a NULL en esos casos -> AVG/SUM los excluyen SOLOS, sin que nadie tenga que
--     acordarse del filtro. La info cruda no se pierde: INI_TS/END_TS siguen ahi para recalcular.
--   El umbral NO es una constante: sale de MAX(hasta) de DIM_CORTE -> se mueve con la data.
--
-- Distribucion real de duraciones (ya sin centinelas): <1 dia 56,6% | 1-7 dias 29,0% |
--   7-30 dias 3,9% | 1-12 meses 7,5% | >1 año 3,0%
--
-- IDEMPOTENTE. Rollback: 005_rollback.sql

BEGIN;

DROP VIEW IF EXISTS DIM_DIFERIDAS;
CREATE VIEW DIM_DIFERIDAS AS
WITH datos AS (
  SELECT *,
         CAST(SUBSTR(EVENT_DATE, 1, 4) AS INTEGER) AS anio,
         CAST(SUBSTR(EVENT_DATE, 6, 2) AS INTEGER) AS mes
  FROM AVM_DATADIF
