  CASE WHEN substr(CASE WHEN d.END_DATE IS NULL THEN NULL WHEN d.END_DATE GLOB '[0-9][0-9][0-9][0-9]-*' THEN substr(d.END_DATE,1,19) ELSE printf('%s-%s-%02d %02d:%s',substr(substr(substr(d.END_DATE,1,instr(d.END_DATE,' ')-1),instr(substr(d.END_DATE,1,instr(d.END_DATE,' ')-1),'/')+1),instr(substr(substr(d.END_DATE,1,instr(d.END_DATE,' ')-1),instr(substr(d.END_DATE,1,instr(d.END_DATE,' ')-1),'/')+1),'/')+1),substr(substr(substr(d.END_DATE,1,instr(d.END_DATE,' ')-1),instr(substr(d.END_DATE,1,instr(d.END_DATE,' ')-1),'/')+1),1,instr(substr(substr(d.END_DATE,1,instr(d.END_DATE,' ')-1),instr(substr(d.END_DATE,1,instr(d.END_DATE,' ')-1),'/')+1),'/')-1),CAST(substr(substr(d.END_DATE,1,instr(d.END_DATE,' ')-1),1,instr(substr(d.END_DATE,1,instr(d.END_DATE,' ')-1),'/')-1) AS INTEGER),CASE WHEN (d.END_DATE LIKE '%p.%m.') AND CAST(substr(substr(substr(d.END_DATE,instr(d.END_DATE,' ')+1),1,instr(substr(d.END_DATE,instr(d.END_DATE,' ')+1),char(8239))-1),1,instr(substr(substr(d.END_DATE,instr(d.END_DATE,' ')+1),1,instr(substr(d.END_DATE,instr(d.END_DATE,' ')+1),char(8239))-1),':')-1) AS INTEGER)<12 THEN CAST(substr(substr(substr(d.END_DATE,instr(d.END_DATE,' ')+1),1,instr(substr(d.END_DATE,instr(d.END_DATE,' ')+1),char(8239))-1),1,instr(substr(substr(d.END_DATE,instr(d.END_DATE,' ')+1),1,instr(substr(d.END_DATE,instr(d.END_DATE,' ')+1),char(8239))-1),':')-1) AS INTEGER)+12 WHEN NOT (d.END_DATE LIKE '%p.%m.') AND CAST(substr(substr(substr(d.END_DATE,instr(d.END_DATE,' ')+1),1,instr(substr(d.END_DATE,instr(d.END_DATE,' ')+1),char(8239))-1),1,instr(substr(substr(d.END_DATE,instr(d.END_DATE,' ')+1),1,instr(substr(d.END_DATE,instr(d.END_DATE,' ')+1),char(8239))-1),':')-1) AS INTEGER)=12 THEN 0 ELSE CAST(substr(substr(substr(d.END_DATE,instr(d.END_DATE,' ')+1),1,instr(substr(d.END_DATE,instr(d.END_DATE,' ')+1),char(8239))-1),1,instr(substr(substr(d.END_DATE,instr(d.END_DATE,' ')+1),1,instr(substr(d.END_DATE,instr(d.END_DATE,' ')+1),char(8239))-1),':')-1) AS INTEGER) END,substr(substr(sub