LSE CAST(substr(substr(substr(d.END_DATE,instr(d.END_DATE,' ')+1),1,instr(substr(d.END_DATE,instr(d.END_DATE,' ')+1),char(8239))-1),1,instr(substr(substr(d.END_DATE,instr(d.END_DATE,' ')+1),1,instr(substr(d.END_DATE,instr(d.END_DATE,' ')+1),char(8239))-1),':')-1) AS INTEGER) END,substr(substr(substr(d.END_DATE,instr(d.END_DATE,' ')+1),1,instr(substr(d.END_DATE,instr(d.END_DATE,' ')+1),char(8239))-1),instr(substr(substr(d.END_DATE,instr(d.END_DATE,' ')+1),1,instr(substr(d.END_DATE,instr(d.END_DATE,' ')+1),char(8239))-1),':')+1)) END) - julianday(CASE WHEN d.INI_DATE IS NULL THEN NULL WHEN d.INI_DATE GLOB '[0-9][0-9][0-9][0-9]-*' THEN substr(d.INI_DATE,1,19) ELSE printf('%s-%s-%02d %02d:%s',substr(substr(substr(d.INI_DATE,1,instr(d.INI_DATE,' ')-1),instr(substr(d.INI_DATE,1,instr(d.INI_DATE,' ')-1),'/')+1),instr(substr(substr(d.INI_DATE,1,instr(d.INI_DATE,' ')-1),instr(substr(d.INI_DATE,1,instr(d.INI_DATE,' ')-1),'/')+1),'/')+1),substr(substr(substr(d.INI_DATE,1,instr(d.INI_DATE,' ')-1),instr(substr(d.INI_DATE,1,instr(d.INI_DATE,' ')-1),'/')+1),1,instr(substr(substr(d.INI_DATE,1,instr(d.INI_DATE,' ')-1),instr(substr(d.INI_DATE,1,instr(d.INI_DATE,' ')-1),'/')+1),'/')-1),CAST(substr(substr(d.INI_DATE,1,instr(d.INI_DATE,' ')-1),1,instr(substr(d.INI_DATE,1,instr(d.INI_DATE,' ')-1),'/')-1) AS INTEGER),CASE WHEN (d.INI_DATE LIKE '%p.%m.') AND CAST(substr(substr(substr(d.INI_DATE,instr(d.INI_DATE,' ')+1),1,instr(substr(d.INI_DATE,instr(d.INI_DATE,' ')+1),char(8239))-1),1,instr(substr(substr(d.INI_DATE,instr(d.INI_DATE,' ')+1),1,instr(substr(d.INI_DATE,instr(d.INI_DATE,' ')+1),char(8239))-1),':')-1) AS INTEGER)<12 THEN CAST(substr(substr(substr(d.INI_DATE,instr(d.INI_DATE,' ')+1),1,instr(substr(d.INI_DATE,instr(d.INI_DATE,' ')+1),char(8239))-1),1,instr(substr(substr(d.INI_DATE,instr(d.INI_DATE,' ')+1),1,instr(substr(d.INI_DATE,instr(d.INI_DATE,' ')+1),char(8239))-1),':')-1) AS INTEGER)+12 WHEN NOT (d.INI_DATE LIKE '%p.%m.') AND CAST(substr(substr(substr(d.INI_DATE,instr(d.INI